/* the waves: one girl per sister in each batch (a sister's sets can be re-cut for one new girl per pass) */
(function(){
  if(typeof ACAD==="undefined"||typeof ACAD_WAVE!=="function"||typeof SV249==="undefined")return;
  const T0=performance.now(),by={};SV249.girls.forEach(g=>{by[g.k]=g});
  /* the girls who stand apart from the Academy's Houses (counts of "the hundred" leave them out) */
  ACAD.APART=new Set(SV249.girls.map(g=>g.k));
  SV249.batches.forEach((ks,i)=>{const L={},H={},M={},S={};ks.forEach(k=>{L[k]=SV249.lore[k];H[k]=SV249.heads[k];M[k]=SV249.men[k];S[k]=SV249.sig[k]});
    try{ACAD_WAVE(ks.map(k=>by[k]),L,H,M,S,"249_"+i,null,ACAD.WAVE_ONLY)}catch(e){if(window.console)console.warn("v249 wave "+i,e)}});
  /* her boyfriend and headmistress by name */
  const T=id=>typeof tplById==="function"?tplById(id):null;
  Object.entries(SV249.manNames).forEach(([k,n])=>{const t=T(k+"man");if(t)t.bio=Object.assign({},t.bio||{},{fullName:n})});
  Object.entries(SV249.headNames).forEach(([k,n])=>{const t=T(k+"head");if(t)t.bio=Object.assign({},t.bio||{},{fullName:n})});
  ACAD.SV249_MS=Math.round(performance.now()-T0);
})();

