    if(sp.tags.length)steps.push(["tag",sp.tags.join(", ")]);
    (p.texts||[]).forEach(it=>steps.push(["text",JSON.parse(JSON.stringify(it))]));
    PA.parse(p).forEach(a=>steps.push(["act",a]));
    Object.entries(p.c1||{}).forEach(([f,v])=>steps.push(["c1",[f,v]]));Object.entries(p.pc||{}).forEach(([f,v])=>steps.push(["pc",[f,v]]));
